"use strict";(self.webpackChunkstrapi_docs=self.webpackChunkstrapi_docs||[]).push([[89677],{27386:e=>{e.exports=JSON.parse('{"tag":{"label":"controllers","permalink":"/tags/controllers","allTagsPath":"/tags","count":12,"items":[{"id":"cms/backend-customization","title":"Back-end customization","description":"All elements of Strapi\'s back end, like routes, policies, middlewares, controllers, services, models, requests, responses, and webhooks, can be customized.","permalink":"/cms/backend-customization"},{"id":"cms/backend-customization/controllers","title":"Controllers","description":"Controllers bundle actions that handle business logic for each route within Strapi\u2019s MVC pattern. This documentation demonstrates generating controllers, extending core ones with createCoreController, and delegating heavy logic to services.","permalink":"/cms/backend-customization/controllers"},{"id":"cms/backend-customization/examples/services-and-controllers","title":"Custom services and controllers","description":"Learn how to authenticate use custom services and controllers using our FoodAdvisor example","permalink":"/cms/backend-customization/examples/services-and-controllers"},{"id":"cms/features/email","title":"Email","description":"Send email from your server or externals providers.","permalink":"/cms/features/email"},{"id":"cms/backend-customization/middlewares","title":"Middlewares","description":"Middlewares alter the request or response flow at application or API levels. This documentation distinguishes global versus route middlewares and illustrates custom implementations with generation patterns.","permalink":"/cms/backend-customization/middlewares"},{"id":"cms/plugins-development/plugins-extension","title":"Plugins extension","description":"Existing plugins can be overriden by placing code in /src/extensions or using global register/bootstrap hooks. Instructions in this documentation cover reshaping plugin content-type schemas or server logic \u2014 altough upstream updates may break extensions.","permalink":"/cms/plugins-development/plugins-extension"},{"id":"cms/backend-customization/policies","title":"Policies","description":"Strapi policies are functions that execute specific logic on each request before it reaches the controller. Policies can be customized according to your needs.","permalink":"/cms/backend-customization/policies"},{"id":"cms/migration/v4-to-v5/breaking-changes/default-input-validation","title":"REST API input is validated by default in controllers","description":"In Strapi 5, REST API input is validated by default in controllers, instead of accepting invalid data and sanitizing it silently.","permalink":"/cms/migration/v4-to-v5/breaking-changes/default-input-validation"},{"id":"cms/backend-customization/routes","title":"Routes","description":"Strapi routes handle requests to your content and are auto-generated for your content-types. Routes can be customized according to your needs.","permalink":"/cms/backend-customization/routes"},{"id":"cms/plugins-development/server-api","title":"Server API for plugins","description":"Overview of the Strapi Server API for plugins, with entry file, lifecycle hooks, routes, controllers, services, policies, middlewares, and configuration.","permalink":"/cms/plugins-development/server-api"},{"id":"cms/plugins-development/server-controllers-services","title":"Server controllers & services","description":"Handle HTTP requests in plugin controllers and organize reusable business logic in plugin services.","permalink":"/cms/plugins-development/server-controllers-services"},{"id":"cms/backend-customization/services","title":"Services","description":"Strapi services are a set of reusable functions, useful to simplify controllers logic.","permalink":"/cms/backend-customization/services"}],"unlisted":false}}')}}]);